mapper.select:
SELECT * FROM (SELECT fb.NO, fb.title, fb.content, M.ID, fb.created_date, fb.view_count, ROW_NUMBER() over(ORDER BY created_date desc)AS rn FROM FREE_BOARD fb JOIN MEMBER m ON m.NO = fb.AUTHOR_NO
WHERE title LIKE '%' || #{searchDTO.searchText} || '%'
WHERE content LIKE '%' || #{searchDTO.searchText} || '%'
WHERE m.id LIKE '%' || #{searchDTO.searchText} || '%'
) WHERE rn BETWEEN #{pi.offset} AND #{pi.limit}

