	UPDATE free_board
	SET VIEW_COUNT = VIEW_COUNT+1
	WHERE free_Board.no = #{boardNo}

UPDATE FREE_BOARD
SET FREE_BOARD.title = #{boardTitle},
	FREE_BOARD.content = #{boardContent}
WHERE free_Board.no = #{boardNo}
